'use strict';
(() => {
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const copy=v=>structuredClone(v), id=p=>p+'-'+crypto.randomUUID(), days=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];
let cfg,status,usage={},projects=[],runs=[],visibility=[],draft=null,dialogState=null,dialogStack=[],returnFocus=null,dialogScroll=0,returnSelector='',saveBusy=false,route=readRoute(),lastSync=0,activity=new Map(),pollBusy=false,lastPaint='';
const sections={subscriptions:'AI Subscriptions',power_bands:'Named Power Bands',time_windows:'Named Time Windows'};
const labels={automations:'automation',subscriptions:'subscription',sequences:'launch sequence',presets:'permission preset',power_bands:'power band',time_windows:'time window',overdrive_windows:'overdrive window',projects:'project'};
const recurrence=()=>({days:[1,2,3,4,5],start:'22:00',end:'06:00',timezone:Intl.DateTimeFormat().resolvedOptions().timeZone||'America/Chicago',every_weeks:1,anchor_date:'2026-01-05'});
function readRoute(){const q=new URLSearchParams(location.search);return {page:location.pathname==='/settings'?'settings':location.pathname==='/project'?'project':'all',project:q.get('project')||'',tab:q.get('tab')||'plans',filter:q.get('filter')||'queued',section:q.get('section')||'subscriptions',subscription:q.get('subscription')||'',return:q.get('return')||'/'};}
const projectURL=(p,tab='plans',filter='queued')=>'/project?'+new URLSearchParams({project:p,tab,filter});
function saveView(){history.replaceState({...history.state,scroll:scrollY},'');if(draft)sessionStorage.setItem('conductor-draft',JSON.stringify(draft));}
function navigate(url){saveView();history.pushState({scroll:0},'',url);route=readRoute();render();scrollTo(0,0);}
addEventListener('popstate',()=>{route=readRoute();render();requestAnimationFrame(()=>scrollTo(0,history.state?.scroll||0));});
async function api(path,body){const r=await fetch('/api/conductor/'+path,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});let j;try{j=await r.json()}catch{throw Error(await r.text().catch(()=>r.statusText))}if(!r.ok||j.ok===false)throw Error(j.error?.message||j.message||r.statusText);return j.data??j;}
function notify(message){$('#notices').textContent=message;setTimeout(()=>{$('#notices').textContent=''},5000);}
async function commit(next,expected=cfg.revision){cfg=await api('config',{expected_revision:expected,config:next});await refresh(false);notify('Saved. Applies at the next admission.');}
async function refresh(paint=true){if(pollBusy)return;pollBusy=true;try{const [c,s,p,u,rs,vs]=await Promise.all([api('config'),api('status'),api('projects'),api('usage'),api('runs'),api('visibility')]);const initial=!cfg,changed=initial||cfg.revision!==c.revision,viewKey=JSON.stringify([c,s.state,s.queues,s.candidates,s.occurrences,p,u,rs,vs]);cfg=c;status=s;projects=p;usage=u.usage||u;visibility=Array.isArray(vs)?vs:vs.projects||[];runs=Array.isArray(rs)?rs:rs.runs||[];lastSync=Date.now();if(paint&&(initial||(viewKey!==lastPaint&&!dialogState&&!draft&&!document.activeElement?.matches('input,select,textarea')))){const y=scrollY,focus=focusSelector(document.activeElement),positions=[...document.querySelectorAll('.activity-events')].map(x=>[x.parentElement.dataset.activityDetails,x.scrollTop]);render();lastPaint=viewKey;for(const [key,top]of positions){const target=document.querySelector('[data-activity-details="'+CSS.escape(key)+'"] > .activity-events');if(target)target.scrollTop=top;}scrollTo(0,y);if(focus)document.querySelector(focus)?.focus({preventScroll:true})}else{const el=$('#connection');if(el){el.className='';el.textContent='Live · revision '+cfg.revision;}if(changed&&(draft||dialogState))notify('Configuration changed elsewhere. Your draft is preserved; Save checks its revision.');}if(route.tab==='activity')await refreshActivity();}catch(e){const el=$('#connection');if(el){el.className='stale';el.textContent='Reconnecting · '+e.message}else $('#app').innerHTML='<main><h1>Conductor unavailable</h1><p class="error">'+esc(e.message)+'</p><button data-action="retry">Retry</button></main>';}finally{pollBusy=false}}
function button(action,text,attrs='',cls=''){return `<button type="button" data-action="${action}" class="${cls}" ${attrs}>${esc(text)}</button>`;}
function link(url,text,cls=''){return `<a data-nav href="${esc(url)}" class="${cls}">${esc(text)}</a>`;}
let fieldSerial=0;
function field(label,name,value,type='text',attrs=''){const fieldID='field-'+(++fieldSerial);return `<div class="field"><label for="${fieldID}">${esc(label)}</label><input id="${fieldID}" name="${esc(name)}" type="${type}" value="${esc(value)}" ${attrs}></div>`;}
function select(label,name,value,options,attrs=''){const fieldID='field-'+(++fieldSerial);return `<div class="field"><label for="${fieldID}">${esc(label)}</label><select id="${fieldID}" name="${esc(name)}" ${options.every(o=>Array.isArray(o)&&typeof o[0]==='number')?'data-number':''} ${attrs}>${options.map(o=>{let [v,t]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`}).join('')}</select></div>`;}
function check(label,name,value,attrs=''){return `<label class="check"><input type="checkbox" name="${esc(name)}" ${value?'checked':''} ${attrs}>${esc(label)}</label>`;}
function jsonField(label,name,value){const fieldID='field-'+(++fieldSerial);return `<div class="field"><label for="${fieldID}">${esc(label)} · JSON array</label><textarea id="${fieldID}" name="${name}" data-json>${esc(JSON.stringify(value||[],null,2))}</textarea><div class="hint">Each array item is one literal argument. Repeated flags and spaces are preserved.</div></div>`;}
function curveFields(x){return `<div class="grid"><div><h3>Weekly green ceiling · % used</h3>${x.green_curve.map((v,i)=>field('Day '+i,'green_curve.'+i,v,'number','min="0" max="100" step="any"')).join('')}</div><div><h3>Weekly red start · % used</h3>${x.red_curve.map((v,i)=>field('Day '+i,'red_curve.'+i,v,'number','min="0" max="100" step="any"')).join('')}</div></div>`;}
function itemActions(type,item,parent=''){const a=`data-type="${type}" data-id="${esc(item.id)}" data-parent="${esc(parent)}"`;return `<div class="actions">${button('duplicate','Duplicate',a+` aria-label="Duplicate ${esc(item.name)}"`,'link')}${button('delete','Delete',a+` aria-label="Delete ${esc(item.name)}"`,'link danger')}${button('edit','Edit',a+` aria-label="Edit ${esc(item.name)}"`)}</div>`;}
function fullSequences(){return(cfg.subscriptions||[]).flatMap(s=>(s.sequences||[]).map(q=>({...q,subscription:s,label:s.name+' · '+q.name})));}
function sequenceLabel(qid){return fullSequences().find(q=>q.id===qid)?.label||'Unavailable sequence';}
function projectConfig(path=route.project){return cfg.projects.find(p=>p.path===path)}
function queue(p){return status.queues?.find(q=>q.project_id===p?.id)||projects.find(x=>x.path===p?.path)?.queue||{depth:0,ready:0,waiting:0,running:0,plans:[]};}
function render(){if(!cfg)return;const active=projectConfig();$('#app').innerHTML=`<header class="app-header"><a data-nav href="/"><strong>Conductor</strong></a><div class="actions"><span id="connection" class="meta">Live · revision ${cfg.revision}</span>${link('/settings?return='+encodeURIComponent(route.page==='settings'?route.return:location.pathname+location.search),'Settings')}</div></header><main class="${route.page==='settings'?'settings-main':''}"><nav class="breadcrumb" aria-label="Breadcrumb">${link('/','All projects')}${route.page==='project'?` / ${esc(active?.name||projects.find(p=>p.path===route.project)?.name||route.project)} / ${esc(route.tab)}`:route.page==='settings'?` / Settings / ${esc(sections[route.section]||sections.subscriptions)}${(route.section==='subscriptions'||!route.section)&&route.subscription?' / '+esc(cfg.subscriptions.find(s=>s.id===route.subscription)?.name||''):''}`:''}</nav>${route.page==='settings'?settingsView():route.page==='project'?projectView():allProjects()}</main>`;if(route.page==='project'&&draft&&draft.projectPath===route.project&&route.tab==='automations')renderAutomation();if(route.page==='settings'&&route.section==='subscriptions')loadAccountTester();}
function visibilityPanel(path,compact=false){const v=visibility.find(x=>x.project_path===path);if(!v)return '';const evidence=(v.usage||[]).map(u=>{const name=cfg.subscriptions.find(s=>s.id===u.subscription_id)?.name||u.subscription_id;return name+': '+(u.available?'observed '+Math.max(0,Math.round(u.age_seconds))+'s ago · '+u.source:'usage unavailable');}).join(' · ');return `<${compact?'div':'section'} class="${compact?'meta':'panel'}"><strong>${esc(v.state)}${v.effective_sequence?' · '+esc(v.effective_sequence):''}</strong><div>${esc(v.reason)}</div><div>Next opportunity: ${esc(v.next_opportunity||'Waiting for eligibility')}</div><div class="hint">${esc(evidence||'Usage unavailable; no subscription selected')}</div></${compact?'div':'section'}>`;}
function allProjects(){return `<div class="toolbar heading"><h1>All projects</h1>${button('add-project','+ Add project')}</div><div class="panel"><div class="toolbar"><span>${cfg.enabled&&!cfg.paused?'Conductor enabled':'Conductor stopped or paused'} · ${esc(status.state)}</span><div class="actions">${button('control',cfg.enabled&&!cfg.paused?'Pause':'Start',`data-control="${cfg.enabled&&!cfg.paused?'pause':'start'}"`)}${button('control','Stop','data-control="stop"')}${button('tick','Run eligible work')}</div></div><p class="hint">Start permits future admissions. The timer and project switches also apply. Running assignments finish their checkpoint when paused.</p></div><div class="panel">${projects.length?projects.slice().sort((a,b)=>a.name.localeCompare(b.name)).map(p=>{const c=cfg.projects.find(x=>x.path===p.path),q=queue(c||p),cs=status.candidates?.filter(x=>x.project.id===c?.id)||[],next=cs.find(x=>x.selected)||cs[0],run=q.running>0&&runs.find(x=>x.assignment.project_path===p.path&&['running','claimed'].includes(x.status));return `<div class="row">${c?check('Enable '+p.name,'project-enabled',c.enabled,`data-action="toggle-project" data-id="${esc(c.id)}"`):button('register','Configure',`data-path="${esc(p.path)}"`)}<div class="grow">${link(projectURL(p.path),p.name)}<div class="path">${esc(p.path)}</div></div><div>${link(projectURL(p.path),'Queued '+q.depth)}<div class="meta">${q.ready} ready · ${q.waiting} waiting · ${q.running} running</div></div><div class="summary">${esc(run?sequenceLabel(run.assignment.sequence.id)+' · '+run.assignment.plan:next?.reason||(!c?'Not enrolled':'No eligible automation'))}${visibilityPanel(p.path,true)}</div></div>`}).join(''):'<p class="empty">No projects registered. Add an existing project folder to discover its plans.</p>'}</div>`;}
function projectView(){const p=projects.find(x=>x.path===route.project),c=projectConfig();if(!p)return `<h1>Project unavailable</h1><p class="error">This exact project path is not registered or available.</p>${link('/','Back to all projects')}`;const q=queue(c||p);return `<div class="heading"><h1>${esc(p.name)}</h1>${c?button('edit','Project settings',`data-type="projects" data-id="${esc(c.id)}"`):button('register','Configure automations',`data-path="${esc(p.path)}"`)}</div><p class="path">${esc(p.path)}</p><nav class="tabs">${['plans','automations','activity'].map(t=>link(projectURL(p.path,t,route.filter),t==='plans'?'Plans · '+q.depth+' queued':t[0].toUpperCase()+t.slice(1),route.tab===t?'active':'')).join('')}</nav>${p.error?`<p class="error">${esc(p.error)}</p>`:''}${visibilityPanel(p.path)}<div id="project-body">${route.tab==='automations'?automationsView(c):route.tab==='activity'?activityView(p):plansView(p,c)}</div>`;}
function plansView(p,c){const q=queue(c||p),ids=new Set(q.plans.map(x=>x.name));const queued=p.plans.filter(x=>ids.has(x.Name));const active=p.plans.filter(x=>!queued.includes(x));const lists={queued,active,archived:p.archived};return `<section class="panel"><div class="toolbar heading"><h2>Plans</h2><nav class="actions">${Object.keys(lists).map(f=>link(projectURL(p.path,'plans',f),f[0].toUpperCase()+f.slice(1)+' · '+lists[f].length,route.filter===f?'active':'')).join('')}</nav></div>${(lists[route.filter]||queued).map(v=>{const run=runs.find(r=>r.assignment.project_path===p.path&&r.assignment.plan===v.Name);const href=(v.Archived?'/archive?':'/plan?')+new URLSearchParams({project:p.path,...(v.Archived?{file:v.ArchiveFile}:{name:v.Name})});return `<div class="row"><span class="badge ${v.Status?.includes('blocked')?'bad':v.Archived?'good':''}">${esc(v.Archived?'Archived':v.Status||v.Phase||'Planned')}</span><span class="badge">${esc(run?run.assignment.subscription.name:'Unassigned')}</span>${link(href,v.Name,'compact-name')}<span class="grow summary">${esc(v.Goal)}</span><span class="meta">${esc(v.Executing?'Executing '+v.Executing:'Planned '+v.Started)}${v.HasTeams?' · teams '+v.TeamsDone+'/'+v.TeamsTotal:''}</span></div>`}).join('')||'<p class="empty">No plans in this view.</p>'}</section>`;}
function automationsView(p){if(!p)return '<p>Configure this project to add automations. Registration starts disabled.</p>';const list=cfg.automations.filter(a=>a.project_id===p.id);return `<div class="heading"><h2>Automations</h2>${button('add-automation','+ Add automation')}</div><div class="panel">${list.map(a=>{const x=status.candidates.find(x=>x.automation.id===a.id);return `<div class="row">${check('Enable '+a.name,'automation-enabled',a.enabled,`data-action="toggle-automation" data-id="${a.id}"`)}<div class="grow"><strong>${esc(a.name)}</strong><div class="summary">${esc(automationSummary(a))}</div></div><span class="summary">${esc(x?.reason||'Waiting for queued work')}</span>${button('edit-automation','Edit',`data-id="${a.id}"`)}</div>`}).join('')||'<p class="empty">Add an automation to process this project’s staged queue.</p>'}</div><p class="hint">One assignment runs per project. Priorities resolve overlapping automations.</p>`;}
function automationSummary(a){if(a.mode==='overdrive')return 'Follow subscription overdrive · '+(a.participants||[]).map(sequenceLabel).join(', ');return (a.entries||[]).map(e=>sequenceLabel(e.sequence_id)+' through '+e.max_band).join(' → ')+(a.mode==='scheduled'?' · '+((draft?.item.id===a.id&&draft.window?.id===a.window_id?draft.window.name:cfg.time_windows.find(w=>w.id===a.window_id)?.name)||'Missing time window'):' · Any time');}
function activityView(p){return `<div class="heading"><h2>Activity</h2>${button('refresh-activity','Refresh')}</div><div id="activity-rows" class="panel">${activityRows(p)}</div>`;}
const activityExpanded=new Set();
function activityEvent(e){return `<div class="row"><span class="meta">${esc(e.at)}</span><span class="badge">${esc(e.kind)}</span><span class="grow">${esc(e.message)}</span></div>`;}
function activityRows(p){const rs=runs.filter(x=>x.assignment.project_path===p.path).sort((a,b)=>b.started.localeCompare(a.started));return rs.map(r=>{const rid=r.assignment.run_id,events=activity.get(rid)?.events||[],transport=events.filter(e=>e.kind==='activity'&&/^Stream: (content_block_|message_)/.test(e.message)),meaningful=events.filter(e=>!transport.includes(e)),last=meaningful.at(-1),detailKey=rid+':events',transportKey=rid+':stream';return `<section class="activity-run"><div class="row"><span class="badge">${esc(r.status)}</span><strong>${esc(r.assignment.plan)}</strong><span>${esc(r.assignment.subscription.name+' · '+r.assignment.sequence.name)}</span><span class="meta">${esc(r.started)}</span>${last?`<span class="summary">${esc(last.message)}</span>`:''}</div>${events.length?`<details data-activity-details="${esc(detailKey)}" ${activityExpanded.has(detailKey)?'open':''}><summary>Recorded events · ${events.length}</summary><div class="activity-events">${meaningful.map(activityEvent).join('')}${transport.length?`<details data-activity-details="${esc(transportKey)}" ${activityExpanded.has(transportKey)?'open':''}><summary>Provider stream updates · ${transport.length}</summary>${transport.map(activityEvent).join('')}</details>`:''}</div></details>`:`<p class="hint">${activity.get(rid)?.loaded?'No recorded events.':'Loading recorded events…'}</p>`}</section>`;}).join('')||'<p class="empty">No recorded Conductor assignments for this project.</p>';}
document.addEventListener('toggle',e=>{const key=e.target.dataset?.activityDetails;if(key){if(e.target.open)activityExpanded.add(key);else activityExpanded.delete(key);}},true);
async function refreshActivity(){const project=route.project;let changed=false;try{for(const r of runs.filter(x=>x.assignment.project_path===project)){const rid=r.assignment.run_id,old=activity.get(rid)||{cursor:0,events:[]};const page=await api('events?'+new URLSearchParams({run_id:rid,after:old.cursor,limit:100}));const seen=new Set(old.events.map(e=>e.sequence)),incoming=(page.events||[]).filter(e=>page.expired||!seen.has(e.sequence));changed=changed||!old.loaded||!!page.expired||incoming.length>0;activity.set(rid,{loaded:true,cursor:page.cursor||old.cursor,events:(page.expired?[]:old.events).concat(incoming).slice(-500)});}const el=$('#activity-rows');if(el&&changed&&route.project===project&&route.tab==='activity'){const y=scrollY,focused=document.activeElement,focusKey=focused?.tagName==='SUMMARY'?focused.parentElement.dataset.activityDetails:'',positions=[...el.querySelectorAll('.activity-events')].map(x=>[x.parentElement.dataset.activityDetails,x.scrollTop]);el.innerHTML=activityRows({path:project});for(const [key,top]of positions){const target=el.querySelector('[data-activity-details="'+CSS.escape(key)+'"] > .activity-events');if(target)target.scrollTop=top;}if(focusKey)el.querySelector('[data-activity-details="'+CSS.escape(focusKey)+'"] > summary')?.focus({preventScroll:true});scrollTo(0,y);}}catch(e){notify('Activity reconnecting: '+e.message)}}
function settingsView(){const section=sections[route.section]?route.section:'subscriptions';return `<div class="heading">${link(route.return||'/','← Return to '+(route.return?.startsWith('/archive?')||route.return?.startsWith('/plan?')?'plan':route.return?.startsWith('/project?')?'project workspace':'All projects'))}</div><div class="settings"><nav class="rail" aria-label="Settings">${Object.entries(sections).map(([key,label])=>link('/settings?'+new URLSearchParams({section:key,return:route.return}),label,section===key?'active':'')).join('')}</nav><div class="settings-content">${section==='subscriptions'?subscriptionsView():definitionsView(section)}</div></div>`;}
function definitionsView(type){const items=cfg[type]||[];return `<div class="heading"><h2>${sections[type]}</h2>${button('add','+ Add '+labels[type],`data-type="${type}"`)}</div><div class="panel">${items.map(x=>`<div class="row"><strong>${esc(x.name)}</strong>${itemActions(type,x)}<span class="summary">${esc(references(type,x.id).join(', ')||'Not assigned')}</span></div>`).join('')||'<p class="empty">No definitions.</p>'}</div>`;}
function subscriptionsView(){const s=cfg.subscriptions.find(s=>s.id===route.subscription)||cfg.subscriptions[0];if(s&&!route.subscription)route.subscription=s.id;return `<div class="heading"><h2>AI Subscriptions</h2>${button('add','+ Add subscription','data-type="subscriptions"')}</div><nav class="tabs subscription-select">${cfg.subscriptions.map(s=>link('/settings?'+new URLSearchParams({section:'subscriptions',subscription:s.id,return:route.return}),s.name,route.subscription===s.id?'active':'')).join('')}</nav>${s?subscriptionDetail(s):'<p class="empty">Add a subscription using an installed AI CLI or an editable starter template.</p>'}`;}
function usageBars(s){const u=usage[s.id];if(!u)return '<p class="hint">Usage unavailable. Refresh and bind an authenticated account to observe its allowance.</p>';return `<div class="grid">${['weekly','short'].map(k=>{const x=u[k];if(!x)return `<div><strong>${k==='weekly'?'Weekly':'5-hour'}</strong><p class="hint">${k==='short'&&u.short_unsupported?'Unsupported by this subscription':'Unavailable'}</p></div>`;return `<div><strong>${k==='weekly'?'Weekly':'5-hour'} · ${fmt(100-x.used_percent)}% remaining</strong><div class="powerbar" style="background:linear-gradient(to right,var(--accent) 0 ${x.used_percent}%,#e9e7e3 ${x.used_percent}% 100%)"><span class="marker" style="left:${x.used_percent}%"></span></div><span class="hint">${fmt(x.used_percent)}% used · reset ${esc(new Date(x.resets_at).toLocaleString())}${x.reset_trusted?'':' (estimated)'}</span></div>`}).join('')}</div><p class="hint">${esc(u.source)} · observed ${esc(new Date(u.observed_at).toLocaleString())}${u.hard_blocked?' · Provider limit blocks admissions':''}</p>`;}
function subscriptionDetail(s){return `<section class="panel"><div class="heading"><h3>${esc(s.name)}</h3>${itemActions('subscriptions',s)}<span class="badge">${s.enabled?'Enabled':'Disabled'}</span></div><p class="hint">${esc(s.tier||'Plan not specified')} · ${esc(s.executable)} · ${esc(cfg.power_bands.find(p=>p.id===s.power_band_id)?.name||'Unavailable policy')}</p>${usageBars(s)}<div class="actions">${button('probe','Check readiness',`data-id="${s.id}"`)}${button('usage-refresh','Refresh usage / bind account',`data-id="${s.id}"`)}</div><div id="readiness" class="hint"></div><details><summary>Subscription details</summary><p class="hint">Pool: ${esc(s.pool_id||'Unbound')} · Account: ${esc(s.account_id||'Unbound')}<br>Typical weekly reset: ${esc(days[(s.typical_reset?.day||1)-1])} ${esc(s.typical_reset?.time||'')} · ${esc(s.typical_reset?.timezone||'')} (estimate)<br>Freshness limit: ${s.freshness_seconds}s · Shared-pool concurrency: ${s.concurrency}</p></details></section><section class="panel"><div class="heading"><h3>Named Launch Sequences</h3>${button('add','+ Add sequence',`data-type="sequences" data-parent="${s.id}"`)}</div>${(s.sequences||[]).map(q=>`<div class="row"><span>${esc(s.name+' · '+q.name)}</span>${itemActions('sequences',q,s.id)}</div>`).join('')||'<p class="empty">Add a launch definition for this subscription.</p>'}</section><section class="panel"><div class="heading"><h3>Overdrive windows</h3>${button('add','+ Add window',`data-type="overdrive_windows" data-parent="${s.id}"`)}</div>${check('Enable subscription overdrive','overdrive-enabled',s.overdrive_enabled,`data-action="toggle-overdrive" data-id="${s.id}"`)}<p class="hint">Ignore soft power-band restrictions until the target weekly percentage is used. Only participating automations honor these windows.</p>${(s.overdrive_windows||[]).map(w=>`<div class="row">${check(w.name+' ('+fmt(w.target_used_percent)+'% used)','window-enabled',w.enabled,`data-action="toggle-window" data-parent="${s.id}" data-id="${w.id}"`)}${itemActions('overdrive_windows',w,s.id)}</div>`).join('')}<div id="account-tester" class="tester"></div></section>`;}
function references(type,key){const refs=[];if(type==='power_bands')cfg.subscriptions.filter(s=>s.power_band_id===key).forEach(s=>refs.push(s.name));if(type==='time_windows'){cfg.projects.filter(p=>p.window_id===key).forEach(p=>refs.push(p.name));cfg.automations.filter(a=>a.window_id===key).forEach(a=>refs.push(a.name));}if(type==='subscriptions'){const s=cfg.subscriptions.find(s=>s.id===key);for(const q of s?.sequences||[])refs.push(...references('sequences',q.id));}if(type==='sequences')cfg.automations.filter(a=>a.entries?.some(e=>e.sequence_id===key)||a.participants?.includes(key)).forEach(a=>refs.push(a.name));if(type==='presets')cfg.subscriptions.forEach(s=>(s.sequences||[]).filter(q=>q.preset_id===key).forEach(q=>refs.push(s.name+' · '+q.name)));return [...new Set(refs)];}
function collection(config,type,parent){const owner=parent?config.subscriptions.find(s=>s.id===parent):config;if(!owner)throw Error('Owning subscription is unavailable. Reload the list.');return owner[type]||(owner[type]=[]);}
function newItem(type,parent){switch(type){case 'projects':return {id:id('project'),name:'',path:'',enabled:false,paused:false,max_attempts:5,no_progress_seconds:2700,watch_bound:10,max_import:10};case 'subscriptions':return {id:id('subscription'),name:'',enabled:false,adapter:'custom',result_transport:'prompt_file',executable:'',args:['{prompt}'],pool_id:'',account_id:'',tier:'',power_band_id:'universal',concurrency:1,freshness_seconds:300,typical_reset:{day:7,time:'00:00',timezone:recurrence().timezone},usage_command:[],sequences:[],presets:[],overdrive_enabled:false,overdrive_windows:[]};case 'sequences':return {id:id('sequence'),name:'',model:'',reasoning:'',preset_id:'',args:[]};case 'presets':return {id:id('preset'),name:'',args:[]};case 'power_bands':return {...copy(cfg.power_bands.find(p=>p.id==='universal')||cfg.power_bands[0]),id:id('band'),name:''};case 'time_windows':return {id:id('window'),name:'',enabled:true,start_mode:'weekly',hours_before_reset:24,recurrence:recurrence()};case 'overdrive_windows':return {id:id('overdrive'),name:'',enabled:false,target_used_percent:100,start_mode:'weekly',hours_before_reset:24,end_mode:'next_reset',end_day:7,end_time:'00:00',recurrence:recurrence()};}}
function openEditor(type,key='',parent='',duplicate=false,seed){const original=key?collection(cfg,type,parent)?.find(x=>x.id===key):null;if(key&&!original)return notify('Definition unavailable; reload the list.');if(!dialogState){returnFocus=document.activeElement;returnSelector=focusSelector(returnFocus);dialogScroll=scrollY;dialogStack=[];}const item=copy(seed||original||newItem(type,parent));if(duplicate){item.id=id(type);item.name+=' copy';if(type==='subscriptions'){const mapping={};for(const field of ['sequences','presets','overdrive_windows'])for(const child of item[field]||[]){mapping[child.id]=id(field);child.id=mapping[child.id];}for(const q of item.sequences||[])if(mapping[q.preset_id])q.preset_id=mapping[q.preset_id];item.enabled=false;}}dialogState={type,parent,item,revision:cfg.revision,isNew:!original||duplicate};showEditor();}
function recurrenceFields(w,isOverdrive){const r=w.recurrence||(w.recurrence=recurrence());return `<div class="grid">${select('Start relative to','start_mode',w.start_mode,[['weekly','Weekly days and time'],['reset_relative','Hours before trusted reset']])}${w.start_mode==='reset_relative'?field('Hours before reset','hours_before_reset',w.hours_before_reset||24,'number','required min="0.000001" step="any"'):''}</div>${w.start_mode!=='reset_relative'?`<label>Repeat on</label><div class="days">${days.map((d,i)=>check(d,'recurrence.days',r.days?.includes(i+1),`value="${i+1}" data-days`)).join('')}</div><div class="grid">${field('Start time','recurrence.start',r.start,'time')}${!isOverdrive?field('End time','recurrence.end',r.end,'time'):''}${field('Timezone','recurrence.timezone',r.timezone)}${field('Repeat every N weeks','recurrence.every_weeks',r.every_weeks||1,'number','min="1"')}${field('Anchor date','recurrence.anchor_date',r.anchor_date||'2026-01-05','date')}</div><p class="hint">Repeats indefinitely. Overnight windows belong to the start day; equal start/end covers the full selected day.</p>`:field('Display timezone','recurrence.timezone',r.timezone)}${isOverdrive?`<div class="grid">${select('Window ends','end_mode',w.end_mode,[['next_reset','Next trusted weekly reset'],['explicit','Selected weekday and time'],['recurrence','Recurrence end time']])}${w.end_mode==='explicit'?select('End day','end_day',w.end_day||7,days.map((d,i)=>[i+1,d]))+field('End time','end_time',w.end_time||'00:00','time'):w.end_mode==='recurrence'?field('End time','recurrence.end',r.end,'time'):''}</div>`:''}`;}
function editorFields(d){const x=d.item,s=cfg.subscriptions.find(s=>s.id===d.parent);switch(d.type){case 'projects':return `<div class="grid">${field('Project name','name',x.name)}${field('Existing project folder','path',x.path)}</div>${check('Enable future assignments','enabled',x.enabled)}<p class="hint">Registration starts disabled. The existing folder and its plans stay in place.</p>${select('Project-wide time window','window_id',x.window_id||'',[['','Any time'],...cfg.time_windows.map(w=>[w.id,w.name])])}<details><summary>Retry and project limits</summary><div class="grid">${field('Maximum attempts','max_attempts',x.max_attempts,'number','min="1"')}${field('No progress seconds','no_progress_seconds',x.no_progress_seconds,'number','min="1"')}${field('Plan wall-clock cap seconds (0 = none)','plan_cap_seconds',x.plan_cap_seconds||0,'number','min="0"')}${field('Watch bound','watch_bound',x.watch_bound,'number','min="1"')}${field('Maximum imported issues','max_import',x.max_import,'number','min="1"')}</div>${check('Enable issue intake','intake_enabled',x.intake_enabled)}</details>`;
case 'subscriptions':return `${d.isNew?select('Start from an editable template','template','',[['','Custom CLI'],...cfg.subscriptions.map(s=>[s.id,s.name])]):''}<div class="grid">${field('Subscription name','name',x.name)}${field('Plan / tier','tier',x.tier||'','text','list="tiers"')}<datalist id="tiers"><option>Pro</option><option>Max</option><option>Plus</option><option>Team</option><option>Custom</option></datalist>${field('Executable','executable',x.executable)}${select('Adapter','adapter',x.adapter,[['codex','Codex'],['claude','Claude Code'],['custom','Custom CLI']])}${select('Result transport','result_transport',x.result_transport||'prompt_file',[['prompt_file','Result file instructions in prompt'],['argv_file','Result path in literal argument']])}${select('Named power band','power_band_id',x.power_band_id,cfg.power_bands.map(p=>[p.id,p.name]))}${field('Shared pool concurrency','concurrency',x.concurrency,'number','min="1"')}${field('Usage freshness seconds','freshness_seconds',x.freshness_seconds,'number','min="1"')}</div>${check('Enable subscription','enabled',x.enabled)}<p class="hint">An enabled definition still needs verified execution and authentic account usage.</p>${jsonField('Executable arguments','args',x.args)}${jsonField('Usage collector command','usage_command',x.usage_command)}<details><summary>Account binding and typical weekly reset</summary><div class="grid">${field('Sanitized account ID','account_id',x.account_id||'')}${field('Shared allowance pool ID','pool_id',x.pool_id||'')}${select('Typical reset day','typical_reset.day',x.typical_reset?.day||7,days.map((d,i)=>[i+1,d]))}${field('Typical reset time','typical_reset.time',x.typical_reset?.time||'00:00','time')}${field('Timezone','typical_reset.timezone',x.typical_reset?.timezone||recurrence().timezone)}</div><p class="hint">Typical reset is estimated. Authentic provider reset data governs admissions. Refresh usage binds an unbound account.</p></details>`;
case 'sequences':return `<label for="sequence-name">Sequence name</label><div class="fixed-prefix field"><strong>${esc(s.name)} ·</strong><input id="sequence-name" name="name" value="${esc(x.name)}" required></div><div class="grid">${field('Model · optional','model',x.model||'')}${field('Reasoning effort · optional','reasoning',x.reasoning||'')}${select('Permission preset','preset_id',x.preset_id||'',[['','None'],...(s.presets||[]).map(p=>[p.id,p.name])])}</div><div class="actions">${x.preset_id?itemActions('presets',s.presets.find(p=>p.id===x.preset_id)||{id:x.preset_id,name:'preset'},s.id):''}${button('nested-preset','+ Add preset',`data-parent="${s.id}"`)}</div><details><summary>Advanced launch options</summary>${jsonField('Additional literal arguments','args',x.args)}</details><details open><summary>Effective command</summary><pre id="command-preview">Checking command…</pre></details>`;
case 'presets':return field('Permission preset name','name',x.name)+jsonField('Literal permission options','args',x.args);
case 'power_bands':return field('Power band name','name',x.name)+`<p class="hint">Assigned to: ${esc(references('power_bands',x.id).join(', ')||'No subscriptions')}. Edits affect these subscriptions at future admissions.</p><div class="grid"><div class="full">${curveFields(x)}</div>${field('5-hour green ceiling · % used','short_green',x.short_green,'number','min="0" max="100" step="0.1"')}${field('5-hour red start · % used','short_red',x.short_red,'number','min="0" max="100" step="0.1"')}</div><label>Default permitted bands</label><div class="days">${['green','yellow','red'].map(b=>check(b,'allowed_bands',x.allowed_bands?.includes(b),`value="${b}" data-bands`)).join('')}</div><div id="policy-tester" class="tester"></div>`;
case 'time_windows':return field('Time window name','name',x.name)+check('Enable time window','enabled',x.enabled)+recurrenceFields(x,false);
case 'overdrive_windows':return field('Window name','name',x.name)+check('Enable this window','enabled',x.enabled)+field('Target weekly used · %','target_used_percent',x.target_used_percent,'number','required min="0" max="100" step="0.1"')+recurrenceFields(x,true)+`<p class="hint">At the target, normal policy resumes. Overdrive-only automations wait; this is not a forced stop or reserved allowance.</p>`;}}
function lockDialogPage(){document.body.style.top=-dialogScroll+'px';document.body.classList.add('modal-open');}
function showEditor(){const d=dialogState,el=$('#editor'),title=(d.isNew?'Add ':'Edit ')+labels[d.type];el.innerHTML=`<form id="definition-form" class="dialog-frame"><div class="dialog-head"><div><span class="meta">Settings / ${esc(d.parent?cfg.subscriptions.find(s=>s.id===d.parent)?.name:sections[d.type]||'Projects')}</span><h2 id="dialog-title">${esc(title)}</h2></div>${button('close-dialog','Close')}</div><div class="dialog-body"><div id="dialog-error" role="alert"></div>${editorFields(d)}${d.conversion?`<p id="conversion-info" class="notice">${esc(d.conversion.explanation)}<br>${esc(d.conversion.start)} → ${esc(d.conversion.end)} · ${esc(d.conversion.timezone)} · ${esc(d.conversion.source)}</p>`:""}<p class="hint">Used by: ${esc(references(d.type,d.item.id).join(', ')||'No saved references')}</p></div><div class="dialog-foot">${button('close-dialog',dialogStack.length?'Back':'Cancel')}<button class="primary" type="submit">${d.type==='time_windows'?'Save time window':'Save'}</button></div></form>`;if(!el.open){lockDialogPage();el.showModal();}requestAnimationFrame(()=>{(el.querySelector('input:not([type=checkbox])')||el.querySelector('select')||el.querySelector('button'))?.focus({preventScroll:true});});if(d.type==='sequences')previewCommand();if(d.type==='power_bands')loadPolicyTester();}
function capture(form,obj){for(const input of form.querySelectorAll('[name]')){if(input.dataset.days!==undefined||input.dataset.bands!==undefined||input.name==='template'||input.name.startsWith('sample.'))continue;let value=input.type==='checkbox'?input.checked:(input.type==='number'||input.dataset.number!==undefined)?Number(input.value):input.value;if(input.dataset.json!==undefined)value=JSON.parse(input.value);setPath(obj,input.name,value);}if(form.querySelector('[data-days]'))obj.recurrence.days=[...form.querySelectorAll('[data-days]:checked')].map(x=>Number(x.value));if(form.querySelector('[data-bands]'))obj.allowed_bands=[...form.querySelectorAll('[data-bands]:checked')].map(x=>x.value);return obj;}
function setPath(obj,path,value){const bits=path.split('.');for(const b of bits.slice(0,-1))obj=obj[b]||(obj[b]={});obj[bits.at(-1)]=value;}
function focusSelector(el){if(el?.matches('summary')&&el.parentElement.dataset.activityDetails)return '[data-activity-details="'+CSS.escape(el.parentElement.dataset.activityDetails)+'"] > summary';if(el?.matches('a[href]'))return 'a[href="'+CSS.escape(el.getAttribute('href'))+'"]';if(!el?.dataset.action)return '';return '[data-action="'+CSS.escape(el.dataset.action)+'"]'+['type','id','parent'].filter(k=>el.dataset[k]!==undefined).map(k=>'[data-'+k+'="'+CSS.escape(el.dataset[k])+'"]').join('');}
function closeDialog(){if(dialogStack.length){dialogState=dialogStack.pop();dialogState.revision=cfg.revision;showEditor();return;}$('#editor').close();$('#editor').replaceChildren();document.body.classList.remove('modal-open');document.body.style.top='';dialogState=null;render();scrollTo(0,dialogScroll);if(returnFocus?.isConnected)returnFocus.focus({preventScroll:true});else (document.querySelector(`[data-action="edit"][data-id="${CSS.escape(window.lastSavedID||'')}"]`)||(returnSelector?document.querySelector(returnSelector):null))?.focus({preventScroll:true});}
async function saveDefinition(event){event.preventDefault();if(saveBusy)return;saveBusy=true;try{const d=dialogState;capture(event.target,d.item);if(!d.item.name?.trim())throw Error('Name is required.');if(d.isNew&&d.type==='projects')d.item.enabled=false;const next=copy(cfg),list=collection(next,d.type,d.parent),i=list.findIndex(x=>x.id===d.item.id);if(i<0)list.push(copy(d.item));else list[i]=copy(d.item);await commit(next,d.revision);window.lastSavedID=d.item.id;if(d.type==='presets'&&dialogStack.length)dialogStack[dialogStack.length-1].item.preset_id=d.item.id;closeDialog();}catch(e){$('#dialog-error').innerHTML='<p class="error">'+esc(e.message)+'</p>';}finally{saveBusy=false}}
async function previewCommand(){if(dialogState?.type!=='sequences')return;try{capture($('#definition-form'),dialogState.item);const s=cfg.subscriptions.find(s=>s.id===dialogState.parent),out=await api('preview',{subscription:s,sequence:dialogState.item});if($('#command-preview'))$('#command-preview').textContent=out.command||out.preview||JSON.stringify(out.argv||out);}catch(e){if($('#command-preview'))$('#command-preview').textContent=e.message;}}
function openAutomation(key){const p=projectConfig();if(!p)return;const saved=cfg.automations.find(a=>a.id===key);draft={projectPath:p.path,revision:cfg.revision,item:copy(saved||{id:id('automation'),name:'',project_id:p.id,enabled:true,priority:10,mode:'keep_working',entries:fullSequences().slice(0,1).map(q=>({id:id('entry'),sequence_id:q.id,max_band:'green'})),participants:[],honor_engine_overdrive:false,only_during_overdrive:false,run_limit:'drain_queue',on_window_end:'finish_checkpoint'}),window:null,sample:{project_busy:false,queue_available:true,accounts:{},day:1,hour:12,used:38}};if(saved?.window_id)draft.window=copy(cfg.time_windows.find(w=>w.id===saved.window_id));renderAutomation();}
function captureAutomation(){const form=$('#automation-form');if(!form||!draft)return;const a=draft.item;for(const input of form.querySelectorAll('[data-auto]'))setPath(a,input.name,input.type==='checkbox'?input.checked:(input.type==='number'||input.dataset.number!==undefined)?Number(input.value):input.value);if(a.mode==='overdrive')a.participants=[...form.querySelectorAll('[data-participant]:checked')].map(x=>x.value);else a.entries=[...form.querySelectorAll('.entry')].map(row=>({id:row.dataset.id,sequence_id:row.querySelector('[data-sequence]').value,max_band:row.querySelector('[data-band]').value}));if(a.mode==='scheduled'&&draft.window){const wf=form.querySelector('#automation-window');if(wf)capture(wf,draft.window);}saveView();}
function renderAutomation(){if(!draft)return;const a=draft.item,seqs=fullSequences(),p=projectConfig();if(!p)return;a.entries||=[];a.participants||=[];const f=field('Automation name','name',a.name,'text','data-auto required')+field('Priority · lower first','priority',a.priority,'number','data-auto min="0"');$('#project-body').innerHTML=`<form id="automation-form"><div class="heading"><h2>${esc(a.name||'Add automation')}</h2></div><div class="grid">${f}</div><div class="mode-choice">${[['keep_working','Keep it working','Your preferred sequences, in order'],['scheduled','Run on a schedule','The same priorities, within chosen hours'],['overdrive','Follow subscription overdrive','Participants follow subscription windows']].map(([v,t,h])=>`<button type="button" data-action="automation-mode" data-mode="${v}" class="${a.mode===v?'active':''}">${t}<small>${h}</small></button>`).join('')}</div><div class="panel"><div id="automation-error" role="alert"></div>${a.mode==='overdrive'?`<h3>Participating sequences</h3>${seqs.map(q=>`<div class="row">${check(q.label,'participant',a.participants.includes(q.id),`value="${q.id}" data-participant`)}<span class="summary">${q.subscription.overdrive_enabled?(q.subscription.overdrive_windows||[]).filter(w=>w.enabled).length+' enabled windows':'Overdrive disabled'}</span>${link('/settings?'+new URLSearchParams({section:'subscriptions',subscription:q.subscription.id,return:location.pathname+location.search}),'Subscription windows →')}</div>`).join('')}<p class="hint">Overlapping subscriptions prefer the soonest trusted reset. One assignment runs per project.</p>`:`<h3>Try sequences in this order</h3>${a.entries.map((e,i)=>`<div class="entry" data-id="${e.id}"><span>${i+1}</span>${select('Named launch sequence','entry-sequence-'+i,e.sequence_id,seqs.map(q=>[q.id,q.label]),'data-sequence')}${select('Maximum band','entry-band-'+i,e.max_band,[['green','Green only'],['yellow','Green + Yellow'],['red','Green + Yellow + Red']],'data-band')}<div class="actions">${button('entry-up','↑',`data-index="${i}" aria-label="Move row ${i+1} up" ${i===0?'disabled':''}`)}${button('entry-down','↓',`data-index="${i}" aria-label="Move row ${i+1} down" ${i===a.entries.length-1?'disabled':''}`)}${button('entry-remove','−',`data-index="${i}" aria-label="Remove row ${i+1}"`)}</div></div>`).join('')}${button('entry-add','+ Add sequence and band')}<p class="hint">Each row permits its selected band and all greener bands. First eligible row wins; hard limits and project ownership always apply.</p>`}${a.mode==='scheduled'?scheduleEditor():''}<details><summary>Advanced</summary>${check('Enable this automation','enabled',a.enabled,'data-auto')}${a.mode!=='overdrive'?check('Honor subscription overdrive','honor_engine_overdrive',a.honor_engine_overdrive,'data-auto')+check('Only during subscription overdrive','only_during_overdrive',a.only_during_overdrive,'data-auto'):''}</details><div class="notice">${esc(automationSummary(a))}<p class="hint">${a.mode==='overdrive'?'No separate schedule or target. Subscription overdrive windows govern admissions.':'Reevaluate at each bounded checkpoint. An in-flight assignment retains its launch definition.'}</p></div><div id="automation-tester" class="tester"></div><div class="dialog-foot">${cfg.automations.some(x=>x.id===a.id)?button('delete-automation','Delete automation','','link danger'):''}${button('cancel-automation','Cancel')}<button class="primary" type="submit">Save automation</button></div></div></form>`;renderAutomationTester();}
function scheduleEditor(){if(!draft.window){draft.window={...newItem('time_windows'),name:(draft.item.name||'Automation')+' time window'};draft.item.window_id=draft.window.id;}const a=draft.item;return `<hr><div class="grid">${select('Named time window','window_id',a.window_id,[...cfg.time_windows.map(w=>[w.id,w.name]),...(!cfg.time_windows.some(w=>w.id===a.window_id)?[[a.window_id,'New time window']]:[])],'data-auto data-window-picker')}${button('new-auto-window','+ Add time window')}</div><div id="automation-window">${field('Time window name','name',draft.window.name)}${recurrenceFields(draft.window,false)}</div><div class="grid">${select('During the window','run_limit',a.run_limit,[['drain_queue','Keep processing queued plans'],['one_plan','Run one plan']],'data-auto')}${select('When the window ends','on_window_end',a.on_window_end,[['finish_checkpoint','Finish current checkpoint'],['finish_plan','Finish current plan'],['interrupt','Stop immediately']],'data-auto')}</div><p class="hint">${a.on_window_end==='interrupt'?'Stop immediately interrupts the owned process and may leave unfinished edits. Saving authorizes this schedule policy.':a.on_window_end==='finish_plan'?'Finish only the claimed plan after closing, while all other budget, quota, project and ownership gates still permit work.':'An in-flight task/validation checkpoint finishes; no further checkpoint starts outside the window.'}</p>`;}
async function saveAutomation(e){e.preventDefault();try{captureAutomation();if(!draft.item.name.trim())throw Error('Automation name is required.');if(draft.item.mode==='overdrive'&&!draft.item.participants.length)throw Error('Select at least one participating sequence.');if(draft.item.mode!=='overdrive'&&!draft.item.entries.length)throw Error('Add at least one sequence and maximum band.');const next=automationConfig();await commit(next,draft.revision);draft=null;sessionStorage.removeItem('conductor-draft');render();}catch(e){$('#automation-error').innerHTML='<p class="error">'+esc(e.message)+'</p>';}}
function automationConfig(){const c=copy(cfg),a=copy(draft.item),i=c.automations.findIndex(x=>x.id===a.id);if(i<0)c.automations.push(a);else c.automations[i]=a;if(a.mode==='scheduled'&&draft.window){const j=c.time_windows.findIndex(x=>x.id===draft.window.id);if(j<0)c.time_windows.push(copy(draft.window));else c.time_windows[j]=copy(draft.window);}return c;}
function fmt(n){return Number(n).toFixed(1).replace(/\.0$/,'');}
function powerbar(d,used){const u=used??d.weekly_used;if(u==null)return '<p class="hint">Usage unavailable</p>';const g=Math.max(0,Math.min(100,d.green_end||0)),r=Math.max(g,Math.min(100,d.red_start||0)),t=d.overdrive_active?Math.min(100,d.target_used_percent||0):0;const normal=`var(--green) 0 ${g}%,var(--orange) ${g}% ${r}%,var(--red) ${r}% 100%`;const bg=t>0?`var(--overdrive) 0 ${t}%,var(--green) ${t}% ${Math.max(t,g)}%,var(--orange) ${Math.max(t,g)}% ${Math.max(t,r)}%,var(--red) ${Math.max(t,r)}% 100%`:normal;return `<div class="powerbar" role="img" aria-label="${fmt(u)} percent used; ${d.overdrive_active?'overdrive through '+fmt(t)+' percent':'normal power bands'}" style="background:linear-gradient(to right,${bg})"><span class="marker" style="left:${Math.max(0,Math.min(100,u))}%"></span></div><div class="hint">${fmt(u)}% used · ${fmt(100-u)}% remaining${d.overdrive_active?' · target '+fmt(t)+'% used':''}</div>${d.overdrive_active?'<span class="overdrive-active">OVERDRIVE active</span>':'<span class="overdrive-inactive">No overdrive</span>'}`;}
function resultTable(rows,allowance=false){if(!rows.length)return '<table class="results"><tbody><tr><td>Waiting</td><td>No eligible candidate · no queued work or configured sequences</td></tr></tbody></table>';return `<table class="results"><tbody>${rows.map(x=>`<tr class="${x.selected&&x.eligible?'winner':''}"><td>${x.selected&&x.eligible?(allowance?'Allowed:':'Would launch:'):''}</td><td>${esc(x.label||x.subscription?.name+' · '+x.sequence?.name||'Allowance')}</td><td>${esc(x.selected&&x.eligible?(x.selection_reason||'Selected · first eligible candidate'):x.eligible?'Secondary priority · another eligible candidate selected':x.reason||'Waiting')}</td></tr>`).join('')}</tbody></table>`;}
let testerSerial=0,odOptions=[],odOutside=null;
function sampleTime(day,hour,timezone){const today=new Date(),parts=new Intl.DateTimeFormat('en-CA',{timeZone:timezone,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(today),val=k=>+parts.find(x=>x.type===k).value;let utc=new Date(Date.UTC(val('year'),val('month')-1,val('day'),hour));const wd=utc.getUTCDay()||7;utc.setUTCDate(utc.getUTCDate()-wd+day);const target=utc.getTime();for(let i=0;i<3;i++){const p=new Intl.DateTimeFormat('en-US',{timeZone:timezone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',hourCycle:'h23'}).formatToParts(utc),n=k=>+p.find(x=>x.type===k).value;const wall=Date.UTC(n('year'),n('month')-1,n('day'),n('hour'));utc=new Date(utc.getTime()+target-wall);}return utc.toISOString();}
async function renderAutomationTester(){if(!draft||!$('#automation-tester'))return;const a=draft.item,ss=draft.sample,ids=a.mode==='overdrive'?a.participants:a.entries.map(e=>e.sequence_id),subs=[...new Set(ids.map(i=>fullSequences().find(q=>q.id===i)?.subscription.id).filter(Boolean))].map(i=>cfg.subscriptions.find(s=>s.id===i));let controls='';if(a.mode==='overdrive'){try{const options=await api('overdrive-options',{automation:a});odOptions=options.options||options;odOutside=options.outside_available?options.outside_time:null;}catch(e){odOptions=[];}if(!odOptions.some(o=>o.id===ss.window))ss.window='';controls=select('Overdrive window','sample.window',ss.window||'',[['','Outside overdrive window'],...odOptions.map(o=>[o.id,o.label])]);const o=odOptions.find(o=>o.id===ss.window);controls+=`<p class="hint">${o?'Selected overdrive: '+esc(new Date(o.start).toLocaleString('en-US',{timeZone:o.timezone}))+' → '+esc(new Date(o.end).toLocaleString('en-US',{timeZone:o.timezone}))+' · '+o.target_used_percent+'% used target. Sample time: '+esc(new Date(o.sample_time).toLocaleString('en-US',{timeZone:o.timezone}))+' · '+esc(o.timezone):'Outside the selected subscription windows. Saved enable switches remain authoritative.'}</p><label for="sample-used">Sample weekly used · ${ss.used}%</label><input id="sample-used" type="range" min="0" max="100" step="1" name="sample.used" value="${ss.used}"><div id="automation-powerbar"></div>`;}else{if(a.mode==='scheduled'||projectConfig()?.window_id)controls+=`<div class="grid">${select('Sample day','sample.day',ss.day,days.map((d,i)=>[i+1,d]))}${select('Sample hour','sample.hour',ss.hour,Array.from({length:24},(_,i)=>[i,String(i).padStart(2,'0')+':00']))}</div>`;controls+=subs.map(s=>{const v=ss.accounts[s.id]||{band:'green',availability:'ready'};return `<div class="row"><strong>${esc(s.name)}</strong><div class="grid grow">${select('Sample effective band','sample.band.'+s.id,v.band,[['green','Green'],['yellow','Yellow'],['red','Red']])}${select('Sample availability','sample.availability.'+s.id,v.availability,[['ready','Ready'],['stale','Stale usage'],['unavailable','Unavailable'],['exhausted','Hard limit']])}</div></div>`}).join('');}$('#automation-tester').innerHTML=`<div class="toolbar"><h3>Try this automation</h3><span class="badge">Sample · no live changes</span></div>${controls}<div class="days">${check('Project already running','sample.busy',ss.project_busy)}${check('Queued work available','sample.queue',ss.queue_available)}</div><div id="automation-result">Evaluating…</div>`;await evaluateAutomation();}
async function evaluateAutomation(){const serial=++testerSerial;if(!draft)return;try{const a=draft.item,ss=draft.sample,req={project_id:a.project_id,automation_id:a.id,draft:automationConfig(),project_busy:ss.project_busy,queue_available:ss.queue_available,samples:{}};if(a.mode==='overdrive'){const o=odOptions.find(o=>o.id===ss.window);if(o){req.now=o.sample_time;for(const qid of a.participants){const sub=fullSequences().find(q=>q.id===qid)?.subscription;if(sub)req.samples[sub.id]={weekly_used:sub.id===o.subscription_id?ss.used:50,availability:'ready'};}}else{if(!odOutside)throw Error('These windows cover every available sample time. Select a window to try its allowance.');req.now=odOutside;for(const qid of a.participants){const sub=fullSequences().find(q=>q.id===qid)?.subscription;if(sub)req.samples[sub.id]={weekly_used:ss.used,availability:'ready'};}}}else{for(const e of a.entries){const sub=fullSequences().find(q=>q.id===e.sequence_id)?.subscription;if(sub)req.samples[sub.id]=ss.accounts[sub.id]||{band:'green',availability:'ready'};}if(a.mode==='scheduled'||projectConfig()?.window_id)req.now=sampleTime(ss.day,ss.hour,draft.window?.recurrence.timezone||cfg.time_windows.find(w=>w.id===projectConfig()?.window_id)?.recurrence.timezone||'America/Chicago');}const d=await api('evaluate',req);if(serial!==testerSerial||!$('#automation-result'))return;$('#automation-result').innerHTML=resultTable((d.candidates||[]).map(x=>({...x,selection_reason:a.mode==='overdrive'?'Selected · soonest trusted reset; fair tie handling':'Selected · first eligible row'})))+(d.candidates?.length?'':`<p class="hint">${esc(d.state)}</p>`);const o=odOptions.find(o=>o.id===ss.window),b=d.candidates?.find(x=>x.subscription.id===o?.subscription_id)?.budget;if($('#automation-powerbar'))$('#automation-powerbar').innerHTML=b?powerbar(b,ss.used):'<p class="hint">No active sample window</p>';}catch(e){if($('#automation-result'))$('#automation-result').innerHTML='<p class="error">'+esc(e.message)+'</p>';}}
let budgetSample={day:3,weekly:38,short:12,overdrive:false,subscription:''},accountSample={day:1,hour:12,used:38};
try{const saved=JSON.parse(sessionStorage.getItem('conductor-budget-sample')||'null');if(saved&&Number.isFinite(saved.day)&&saved.day>=0&&saved.day<=7)budgetSample={...budgetSample,...saved};}catch{}
function sampleDayLabel(value){const whole=Math.floor(+value),hours=Math.round((+value-whole)*24*10)/10;return whole+' '+(whole===1?'day':'days')+(hours?' + '+hours+' hrs':'')+' of 7 days';}
function testerHeading(title){return `<div class="toolbar"><h3>${title}</h3><span class="badge">Sample · no live changes</span></div>`;}
function loadPolicyTester(){const el=$('#policy-tester');if(!el)return;budgetSample.subscription=budgetSample.subscription||cfg.subscriptions[0]?.id||'';el.innerHTML=testerHeading('Try the power bands')+select('Sample subscription','sample.subscription',budgetSample.subscription,cfg.subscriptions.map(s=>[s.id,s.name]))+`<div class="grid"><div><label for="sample-budget-day">Sample day · ${sampleDayLabel(budgetSample.day)}</label><input id="sample-budget-day" type="range" min="0" max="7" step="0.1" name="sample.budgetDay" value="${budgetSample.day}"></div><div><label for="sample-budget-weekly">Weekly used · ${budgetSample.weekly}%</label><input id="sample-budget-weekly" type="range" min="0" max="100" name="sample.budgetWeekly" value="${budgetSample.weekly}"></div></div><div id="policy-weekly-bar"></div><label for="sample-budget-short">Sample 5-hour used · ${budgetSample.short}%</label><input id="sample-budget-short" type="range" min="0" max="100" name="sample.budgetShort" value="${budgetSample.short}"><div id="policy-short-bar"></div>${check('Honor actual subscription overdrive','sample.budgetOverdrive',budgetSample.overdrive)}<div id="policy-results"></div>`;evaluateBudget();}
async function evaluateBudget(){if(dialogState?.type!=='power_bands')return;try{capture($('#definition-form'),dialogState.item);const d=await api('budget-preview',{subscription_id:budgetSample.subscription,policy:dialogState.item,sample:{day:+budgetSample.day,weekly_used:+budgetSample.weekly,short_used:+budgetSample.short,availability:'ready'},max_band:'green',honor_overdrive:budgetSample.overdrive});$('#policy-weekly-bar').innerHTML=powerbar(d,budgetSample.weekly);$('#policy-short-bar').innerHTML=powerbar({...d,green_end:dialogState.item.short_green,red_start:dialogState.item.short_red,overdrive_active:false},budgetSample.short);$('#policy-results').innerHTML=resultTable([{label:'Budget allowance',eligible:d.allowed,selected:d.allowed,reason:d.reason,selection_reason:d.reason}],true);}catch(e){if($('#policy-results'))$('#policy-results').innerHTML='<p class="error">'+esc(e.message)+'</p>';}}
function loadAccountTester(){const el=$('#account-tester');if(!el)return;const s=cfg.subscriptions.find(s=>s.id===route.subscription);if(!s)return;el.innerHTML=testerHeading('Try this subscription’s windows')+`<div class="grid three">${select('Sample day · subscription timezone','sample.accountDay',accountSample.day,days.map((d,i)=>[i+1,d]))}${select('Sample hour','sample.accountHour',accountSample.hour,Array.from({length:24},(_,i)=>[i,String(i).padStart(2,'0')+':00']))}<div><label for="sample-account-used">Sample weekly used · ${accountSample.used}%</label><input id="sample-account-used" type="range" min="0" max="100" name="sample.accountUsed" value="${accountSample.used}"></div></div><div id="account-bar"></div><div id="account-results"></div>`;evaluateAccount();}
async function evaluateAccount(){const s=cfg.subscriptions.find(s=>s.id===route.subscription);if(!s||!$('#account-bar'))return;try{const d=await api('budget-preview',{subscription_id:s.id,now:sampleTime(+accountSample.day,+accountSample.hour,s.typical_reset.timezone||'America/Chicago'),sample:{weekly_used:+accountSample.used,availability:'ready'},max_band:'green',honor_overdrive:true});$('#account-bar').innerHTML=powerbar(d,accountSample.used);$('#account-results').innerHTML=resultTable([{label:s.name,eligible:d.allowed,selected:d.allowed,reason:d.reason,selection_reason:d.reason}],true);}catch(e){if($('#account-results'))$('#account-results').innerHTML='<p class="error">'+esc(e.message)+'</p>';}}
async function removeDefinition(type,key,parent){const item=collection(cfg,type,parent)?.find(x=>x.id===key);if(!item)return;const refs=references(type,key);returnFocus=document.activeElement;returnSelector=focusSelector(returnFocus);dialogScroll=scrollY;dialogState={type:'delete',targetType:type,parent,item,revision:cfg.revision};$('#editor').innerHTML=`<div class="dialog-frame"><div class="dialog-head"><h2 id="dialog-title">Delete ${esc(labels[type])}</h2>${button('close-dialog','Close')}</div><div class="dialog-body"><p>Delete “${esc(item.name)}”?</p><p class="hint">Used by: ${esc(refs.join(', ')||'No saved references')}</p>${refs.length?'<p class="error">Reassign these references before deleting.</p>':''}<div id="dialog-error" role="alert"></div></div><div class="dialog-foot">${button('close-dialog','Cancel')}${button('confirm-delete',type==='time_windows'?'Delete time window':'Delete',refs.length?'disabled':'','link danger')}</div></div>`;if(!$('#editor').open){lockDialogPage();$('#editor').showModal();}}
async function confirmDelete(){const d=dialogState;try{if(references(d.targetType,d.item.id).length)throw Error('This definition still has saved references.');const next=copy(cfg),list=collection(next,d.targetType,d.parent),i=list.findIndex(x=>x.id===d.item.id);if(i<0)throw Error('Definition is unavailable.');if(d.targetType==='power_bands'&&d.item.id==='universal')throw Error('Universal is the default power band and remains editable.');list.splice(i,1);await commit(next,d.revision);if(d.targetType==='automations'){draft=null;sessionStorage.removeItem('conductor-draft');}closeDialog();}catch(e){$('#dialog-error').innerHTML='<p class="error">'+esc(e.message)+'</p>';}}
async function toggleConfig(update){const c=copy(cfg);update(c);await commit(c);render();}
document.addEventListener('click',async e=>{const nav=e.target.closest('a[data-nav]');if(nav&&!e.metaKey&&!e.ctrlKey&&!e.shiftKey){const u=new URL(nav.href);if(u.pathname==='/plan'||u.pathname==='/archive'){saveView();return;}e.preventDefault();if(draft)captureAutomation();navigate(u.pathname+u.search);return;}const b=e.target.closest('[data-action]');if(!b||b.matches('input[type=checkbox]'))return;const action=b.dataset.action;try{switch(action){case 'retry':await refresh();break;case 'add-project':openEditor('projects');break;case 'register':{const x=newItem('projects');x.path=b.dataset.path;x.name=x.path.split('/').filter(Boolean).at(-1);openEditor('projects','','',false,x);break;}case 'add':openEditor(b.dataset.type,'',b.dataset.parent||'');break;case 'edit':case 'duplicate':if(dialogState?.type==='sequences'&&b.dataset.type==='presets'){capture($('#definition-form'),dialogState.item);dialogStack.push(dialogState);}openEditor(b.dataset.type,b.dataset.id,b.dataset.parent||'',action==='duplicate');break;case 'delete':if(dialogState?.type==='sequences'){capture($('#definition-form'),dialogState.item);dialogStack.push(dialogState);}await removeDefinition(b.dataset.type,b.dataset.id,b.dataset.parent||'');break;case 'confirm-delete':await confirmDelete();break;case 'close-dialog':closeDialog();break;case 'nested-preset':capture($('#definition-form'),dialogState.item);dialogStack.push(dialogState);openEditor('presets','',b.dataset.parent);break;case 'probe':{const out=await api('probe',{subscription_id:b.dataset.id});$('#readiness').textContent=Object.entries(out).map(([k,v])=>k+': '+v).join(' · ');break;}case 'usage-refresh':await api('usage',{subscription_id:b.dataset.id,expected_revision:cfg.revision,bind:true});await refresh();notify('Authentic usage refreshed.');break;case 'control':await api('control',{action:b.dataset.control,expected_revision:cfg.revision});await refresh();break;case 'tick':await api('tick',{expected_revision:cfg.revision});notify('Detached worker requested; admission checks remain authoritative.');await refresh();break;case 'add-automation':openAutomation();break;case 'edit-automation':openAutomation(b.dataset.id);break;case 'cancel-automation':draft=null;sessionStorage.removeItem('conductor-draft');render();break;case 'automation-mode':captureAutomation();draft.item.mode=b.dataset.mode;if(draft.item.mode==='overdrive'){draft.item.honor_engine_overdrive=true;draft.item.only_during_overdrive=true;draft.item.window_id='';}else{draft.item.honor_engine_overdrive=false;draft.item.only_during_overdrive=false;draft.item.window_id=draft.item.mode==='scheduled'?draft.window?.id||'':'';}renderAutomation();break;case 'entry-add':captureAutomation();if(fullSequences().length)draft.item.entries.push({id:id('entry'),sequence_id:fullSequences()[0].id,max_band:'green'});renderAutomation();break;case 'entry-up':case 'entry-down':case 'entry-remove':{captureAutomation();const i=+b.dataset.index,es=draft.item.entries;if(action==='entry-remove')es.splice(i,1);else{const j=i+(action==='entry-up'?-1:1);if(j>=0&&j<es.length)[es[i],es[j]]=[es[j],es[i]];}renderAutomation();break;}case 'new-auto-window':captureAutomation();draft.window={...newItem('time_windows'),name:draft.item.name+' time window'};draft.item.window_id=draft.window.id;renderAutomation();break;case 'delete-automation':await removeDefinition('automations',draft.item.id,'');break;case 'refresh-activity':await refreshActivity();break;}}catch(err){notify(err.message);}});
document.addEventListener('submit',e=>{if(e.target.id==='definition-form')saveDefinition(e);if(e.target.id==='automation-form')saveAutomation(e)});
$('#editor').addEventListener('cancel',e=>{e.preventDefault();closeDialog()});
$('#editor').addEventListener('keydown',e=>{if(e.key!=='Tab')return;const els=[...$('#editor').querySelectorAll('button:not(:disabled),input,select,textarea,a[href],summary')].filter(x=>x.getClientRects().length);if(!els.length)return;const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}});
let debounce;
document.addEventListener('input',e=>{if(dialogState?.conversion&&/^(hours_before_reset|start_mode|end_mode|end_day|end_time|recurrence\.)/.test(e.target.name||'')){dialogState.conversion=null;$('#conversion-info')?.remove();}if(e.target.name?.startsWith('sample.'))sampleChanged(e.target);else if(dialogState?.type==='sequences'){clearTimeout(debounce);debounce=setTimeout(previewCommand,200);}else if(dialogState?.type==='power_bands'){clearTimeout(debounce);debounce=setTimeout(evaluateBudget,200);}});
document.addEventListener('change',async e=>{const x=e.target;if(x.name?.startsWith('sample.')){sampleChanged(x);return;}try{switch(x.dataset.action){case 'toggle-project':await toggleConfig(c=>c.projects.find(p=>p.id===x.dataset.id).enabled=x.checked);return;case 'toggle-automation':await toggleConfig(c=>c.automations.find(a=>a.id===x.dataset.id).enabled=x.checked);return;case 'toggle-overdrive':await toggleConfig(c=>c.subscriptions.find(s=>s.id===x.dataset.id).overdrive_enabled=x.checked);return;case 'toggle-window':await toggleConfig(c=>c.subscriptions.find(s=>s.id===x.dataset.parent).overdrive_windows.find(w=>w.id===x.dataset.id).enabled=x.checked);return;}
if(dialogState&&x.closest('#definition-form')){const d=dialogState,priorMode=d.item.start_mode;capture($('#definition-form'),d.item);if(d.type==='overdrive_windows'&&!d.isNew&&x.name==='start_mode'&&priorMode==='weekly'&&x.value==='reset_relative'){const saved=collection(cfg,d.type,d.parent).find(w=>w.id===d.item.id);if(JSON.stringify(saved?.recurrence)!==JSON.stringify(d.item.recurrence)||saved?.end_mode!==d.item.end_mode||saved?.end_day!==d.item.end_day||saved?.end_time!==d.item.end_time){d.item.start_mode=priorMode;showEditor();$('#dialog-error').textContent='Save timing changes before converting this window.';return;}try{const converted=await api('overdrive-conversion',{subscription_id:d.parent,window_id:d.item.id});if(dialogState!==d)return;if(converted.revision!==d.revision)throw Error('Configuration changed. Reopen the window before converting.');d.item={...converted.window,name:d.item.name,enabled:d.item.enabled,target_used_percent:d.item.target_used_percent};d.conversion=converted;showEditor();}catch(err){d.item.start_mode=priorMode;showEditor();$('#dialog-error').textContent=err.message;}return;}if(x.name==='template'&&x.value){const t=copy(cfg.subscriptions.find(s=>s.id===x.value)),mapping={};t.id=dialogState.item.id;t.name=t.name+' account';t.enabled=false;t.account_id='';t.pool_id='';for(const key of ['sequences','presets','overdrive_windows'])for(const child of t[key]||[]){mapping[child.id]=id(key);child.id=mapping[child.id];}for(const q of t.sequences||[])if(mapping[q.preset_id])q.preset_id=mapping[q.preset_id];dialogState.item=t;showEditor();}else if(['start_mode','end_mode','preset_id'].includes(x.name))showEditor();return;}
if(draft&&x.closest('#automation-form')){captureAutomation();if(x.dataset.windowPicker!==undefined){draft.window=copy(cfg.time_windows.find(w=>w.id===x.value));renderAutomation();}else if(['on_window_end','start_mode','end_mode'].includes(x.name))renderAutomation();else renderAutomationTester();}}catch(err){notify(err.message);}});
function sampleChanged(x){const n=x.name,v=x.type==='checkbox'?x.checked:x.value;if(n.startsWith('sample.account')){if(n==='sample.accountDay')accountSample.day=+v;if(n==='sample.accountHour')accountSample.hour=+v;if(n==='sample.accountUsed'){accountSample.used=+v;x.previousElementSibling.textContent='Sample weekly used · '+v+'%';}evaluateAccount();return;}if(n.startsWith('sample.budget')||n==='sample.subscription'){if(n==='sample.subscription')budgetSample.subscription=v;if(n==='sample.budgetDay')budgetSample.day=+v;if(n==='sample.budgetWeekly')budgetSample.weekly=+v;if(n==='sample.budgetShort')budgetSample.short=+v;if(n==='sample.budgetOverdrive')budgetSample.overdrive=v;if(x.type==='range')x.previousElementSibling.textContent=n==='sample.budgetDay'?'Sample day · '+sampleDayLabel(v):(n==='sample.budgetShort'?'Sample 5-hour used · ':'Weekly used · ')+v+'%';sessionStorage.setItem('conductor-budget-sample',JSON.stringify(budgetSample));evaluateBudget();return;}if(!draft)return;const ss=draft.sample;if(n==='sample.window'){ss.window=v;renderAutomationTester();return;}if(n==='sample.used'){ss.used=+v;x.previousElementSibling.textContent='Sample weekly used · '+v+'%';}if(n==='sample.day')ss.day=+v;if(n==='sample.hour')ss.hour=+v;if(n==='sample.busy')ss.project_busy=v;if(n==='sample.queue')ss.queue_available=v;if(n.startsWith('sample.band.')||n.startsWith('sample.availability.')){const sub=n.split('.').slice(2).join('.');ss.accounts[sub]||={band:'green',availability:'ready'};ss.accounts[sub][n.split('.')[1]]=v;}evaluateAutomation();}
try{const saved=JSON.parse(sessionStorage.getItem('conductor-draft'));if(saved)draft=saved;}catch{}
refresh();setInterval(()=>{if(!document.hidden)refresh()},3000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh()});
})();
